function repaintRect(ctx, rect, orderedCandidates) {
  // 前提：rect 与绘图命令同一坐标系；候选包含所需背景并按 z 排序。
  const { x, y, width, height } = rect;
  const clip = new Path2D();
  clip.rect(x, y, width, height);
  ctx.save();
  try {
    ctx.clip(clip);
    ctx.clearRect(x, y, width, height);
    for (const shape of orderedCandidates) {
      ctx.save();
      try { shape.draw(ctx); }
      finally { ctx.restore(); }
    }
  } finally { ctx.restore(); }
}

