import { ref, watch, toValue } from 'vue';
export function useResult(source, load) {
  const result = ref(null);
  const error = ref(null);
  watch(() => toValue(source), async (key, _, onCleanup) => {
    let active = true;
    const controller = new AbortController();
    onCleanup(() => { active = false; controller.abort(); });
    error.value = null;
    try {
      const value = await load(key, controller.signal);
      if (active) result.value = value;
    } catch (e) {
      if (active) error.value = e;
    }
  }, { immediate: true });
  return { result, error };
}

