async function prepareRows(rows, transform, signal) {
  const staging = [];
  let sliceStart = performance.now();
  for (const row of rows) {
    signal.throwIfAborted();
    staging.push(transform(row));
    if (performance.now() - sliceStart >= 8) {
      if (globalThis.scheduler?.yield)
        await globalThis.scheduler.yield();
      else await new Promise(resolve => setTimeout(resolve, 0));
      sliceStart = performance.now();
    }
  }
  signal.throwIfAborted();
  return staging; // 调用方验证后再发布
}

function budget(previous, current, maxBytes, maxGrowth) {
  const values = [previous, current, maxBytes, maxGrowth];
  if (values.some(x => !Number.isFinite(x) || x < 0))
    throw new TypeError('invalid budget input');
  const growth = previous === 0 ? null :
    (current - previous) / previous;
  return {
    growth,
    pass: current <= maxBytes &&
      (growth === null || growth <= maxGrowth)
  };
}
