function createLatestGate() {
  let epoch = 0, controller = null;
  return {
    begin() {
      const previous = controller;
      const own = new AbortController();
      const id = ++epoch;
      controller = own;
      previous?.abort();
      return {
        signal: own.signal,
        commit(write) {
          if (id !== epoch || own.signal.aborted) return false;
          write();
          return true;
        }
      };
    },
    cancel() {
      const previous = controller;
      controller = null;
      ++epoch;
      previous?.abort();
    }
  };
}
const gate = createLatestGate();
