function safeCitation(raw, origins, base = 'https://kb.example/') {
  if (typeof raw !== 'string' || /[\u0000-\u0020\u007f]/.test(raw)) return null;
  try {
    const url = new URL(raw, base);
    if (url.protocol !== 'https:' || url.username || url.password) return null;
    return origins.has(url.origin) ? url.href : null;
  } catch { return null; }
}
const allowed = new Set(['https://kb.example']);
console.assert(safeCitation('/docs/42', allowed) === 'https://kb.example/docs/42');
console.assert(safeCitation('https://kb.example.evil.test/', allowed) === null);
console.assert(safeCitation('javascript:alert(1)', allowed) === null);

function costPerSuccess(tasks) {
  let total = 0, success = 0;
  for (const task of tasks) {
    total += task.costs.reduce((sum, value) => sum + value, 0);
    if (task.status === 'succeeded') success++;
  }
  return { total, success, perSuccess: success ? total / success : null };
}
// 金额使用统一最小货币单位，示例均为虚构任务。
const result = costPerSuccess([
  { status: 'succeeded', costs: [2, 1] },
  { status: 'succeeded', costs: [4] },
  { status: 'failed', costs: [5, 3] }
]);
console.assert(result.total === 15 && result.perSuccess === 7.5);
